import { type Product } from '../lib/api';

// Map a condition abbreviation to a Tailwind color string for the badge
function conditionColor(abbreviation: string): string {
  const map: Record<string, string> = {
    'M':   'text-tertiary border-tertiary/30 shadow-[0_0_10px_rgba(233,196,0,0.3)]',
    'NM':  'text-[#4ADE80] border-[#4ADE80]/30',
    'LP':  'text-tertiary-fixed border-tertiary-fixed/30',
    'MP':  'text-secondary border-secondary/30',
    'HP':  'text-error border-error/30',
    'DMG': 'text-on-surface-variant border-outline-variant/30',
    'GD':  'text-tertiary border-tertiary/30',
  };
  return map[abbreviation] ?? 'text-on-surface-variant border-outline-variant/30';
}

function formatPrice(price: number): string {
  return 'Rp ' + price.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

interface CatalogItemProps {
  product: Product;
}

export default function CatalogItem({ product }: CatalogItemProps) {
  const primaryImage = product.images?.find(i => i.is_primary) || product.images?.[0];
  const cond = product.condition;
  const color = cond ? conditionColor(cond.abbreviation) : 'text-on-surface-variant border-outline-variant/30';

  return (
    <div className="group relative flex flex-col bg-surface-container-high rounded-xl overflow-hidden transition-all duration-300 hover:-translate-y-2 card-glow">
      <div className="relative aspect-[3/4] overflow-hidden">
        {primaryImage ? (
          <img
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
            alt={product.name}
            src={primaryImage.url}
          />
        ) : (
          <div className="w-full h-full bg-surface-container-low flex items-center justify-center">
            <span className="material-symbols-outlined text-5xl text-on-surface-variant/20">image</span>
          </div>
        )}
        <div className="absolute inset-0 holographic-overlay opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

        {/* Graded badge */}
        {product.graded_data && (
          <div className="absolute top-3 left-3 px-3 py-1 rounded-full bg-secondary/20 backdrop-blur text-secondary text-[10px] font-bold uppercase tracking-tighter border border-secondary/30">
            {product.graded_data}
          </div>
        )}

        {/* Condition badge */}
        {cond && (
          <div className={`absolute top-3 right-3 px-3 py-1 rounded-full bg-surface-bright/90 backdrop-blur ${color} text-[10px] font-bold uppercase tracking-tighter border`}>
            {cond.abbreviation}
          </div>
        )}
      </div>

      <div className="p-5 flex flex-col flex-grow">
        <span className="text-[10px] text-primary font-bold uppercase tracking-widest mb-1">
          {product.collection || product.categories?.map(c => c.name).join(', ') || '—'}
        </span>
        <h3 className="font-headline text-lg font-bold leading-tight mb-4 group-hover:text-primary transition-colors text-[#F5F8F8]">
          {product.name}
        </h3>
        <div className="mt-auto flex items-center justify-between">
          <span className="text-xl font-extrabold text-[#00D4FF]">{formatPrice(product.price)}</span>
          <button className="p-2 rounded-full bg-primary/10 text-primary hover:bg-primary hover:text-on-primary transition-all">
            <span className="material-symbols-outlined">add_shopping_cart</span>
          </button>
        </div>
      </div>
    </div>
  );
}
